// ArchiveProduct runs the :execrows query against mysql.
func (q *mysqlQueries) ArchiveProduct(ctx context.Context, db DBTX, arg ArchiveProductParams) (int64, error) {
	result, err := db.ExecContext(ctx, q.archiveProduct,
		arg.ID,
		arg.Scope,
	)
	if err != nil {
		return 0, err
	}

	return result.RowsAffected()
}

